def add_heads_and_offences(apps, schema_editor):
    """Existing installations get the new revenue heads and the standard offence schedule."""
    RevenueHead = apps.get_model("finance", "RevenueHead")
    Offence = apps.get_model("finance", "Offence")
    if not RevenueHead.objects.exists():
        return  # a fresh database: seed_council creates everything
    vote = getattr(RevenueHead.objects.filter(code="FINES").first(), "budget_line", None)
    for code, name, cat in (("PENALTY", "Late payment penalties", "FINES"), ("TROPHY", "CAMPFIRE trophy fees", "FEES"),
                            ("NAT-RES", "Natural resources permits & royalties", "FEES")):
        RevenueHead.objects.get_or_create(code=code, defaults=dict(name=name, category=cat, default_amount=0, frequency="ONCE", budget_line=vote))
    from core.management.commands.seed_council import OFFENCES

    for code, name, by_law, fine in OFFENCES:
        Offence.objects.get_or_create(code=code, defaults=dict(name=name, by_law=by_law, default_fine=fine))


